@props(['orientation' => 'vertical'])

@php
    use Knppy\Ui\Facades\Ui;

    $orientations = [
        'vertical' => 'flex-col [&>*]:w-full [&>.sr-only]:w-auto',
        'horizontal' => 'flex-row items-center [&>[data-slot=field-label]]:flex-auto has-[>[data-slot=field-content]]:items-start has-[>[data-slot=field-content]]:[&>[role=checkbox],[role=radio]]:mt-px',
        'responsive' => 'flex-col @md/field-group:flex-row @md/field-group:items-center [&>*]:w-full @md/field-group:[&>*]:w-auto [&>.sr-only]:w-auto @md/field-group:[&>[data-slot=field-label]]:flex-auto @md/field-group:has-[>[data-slot=field-content]]:items-start @md/field-group:has-[>[data-slot=field-content]]:[&>[role=checkbox],[role=radio]]:mt-px',
    ];
    $classes = Ui::classes()
        ->add('group/field flex w-full gap-3 data-[invalid=true]:text-destructive')
        ->add($orientations[$orientation] ?? $orientations['vertical'])
        ->add($attributes['class'] ?? '');
@endphp

<div
    role="group"
    data-slot="field"
    data-orientation="{{ $orientation }}"
    {{ $attributes->twMerge(['class' => $classes]) }}
>
    {{ $slot }}
</div>

@props(['errors' => []])

@php
    $messages = collect($errors)
        ->map(function ($error) {
            if (is_string($error)) {
                return $error;
            }

            if (is_array($error)) {
                return $error['message'] ?? null;
            }

            return is_object($error) ? ($error->message ?? null) : null;
        })
        ->filter()
        ->unique()
        ->values();
    $hasContent = $slot->isNotEmpty() || $messages->isNotEmpty();
@endphp

@if ($hasContent)
    <div
        role="alert"
        data-slot="field-error"
        {{ $attributes->twMerge(['class' => 'text-sm font-normal text-destructive']) }}
    >
        @if ($slot->isNotEmpty())
            {{ $slot }}
        @elseif ($messages->count() === 1)
            {{ $messages->first() }}
        @else
            <ul class="ml-4 flex list-disc flex-col gap-1">
                @foreach ($messages as $message)
                    <li>{{ $message }}</li>
                @endforeach
            </ul>
        @endif
    </div>
@endif

@php
    $hasContent = $slot->isNotEmpty();
@endphp

<div
    data-slot="field-separator"
    data-content="{{ $hasContent ? 'true' : 'false' }}"
    {{ $attributes->twMerge(['class' => 'relative -my-2 h-5 text-sm group-data-[variant=outline]/field-group:-mb-2']) }}
>
    <x-ui.separator class="absolute inset-0 top-1/2" />
    @if ($hasContent)
        <span
            data-slot="field-separator-content"
            class="bg-background text-muted-foreground relative mx-auto block w-fit px-2"
        >{{ $slot }}</span>
    @endif
</div>
